class Solution:
    def minimumPartitionScore(self, nums, k):
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums): pre[i + 1] = pre[i] + x
        INF = float('inf')
        dp = [INF] * (n + 1); dp[0] = 0
        for _ in range(k):
            nd = [INF] * (n + 1)
            for i in range(1, n + 1):
                for p in range(i):
                    if dp[p] < INF:
                        s = pre[i] - pre[p]
                        v = dp[p] + s * (s + 1) // 2
                        if v < nd[i]: nd[i] = v
            dp = nd
        return dp[n]

