class Solution {
public:
    long long minimumPartitionScore(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        const long long INF = LLONG_MAX / 4;
        vector<long long> dp(n + 1, INF), nd(n + 1, INF);
        dp[0] = 0;
        for (int j = 0; j < k; j++) {
            fill(nd.begin(), nd.end(), INF);
            for (int i = 1; i <= n; i++)
                for (int p = 0; p < i; p++) {
                    long long s = pre[i] - pre[p];
                    nd[i] = min(nd[i], dp[p] + s * (s + 1) / 2);
                }
            swap(dp, nd);
        }
        return dp[n];
    }
};

