    void rec(int lo, int hi, int ol, int oh) {
        if (lo > hi) return;
        int mid = (lo + hi) / 2;
        long long best = LLONG_MAX / 4; int bo = ol;
        for (int p = ol; p <= min(mid - 1, oh); p++) {
            long long s = pre[mid] - pre[p];
            long long v = dp[p] + s * (s + 1) / 2;
            if (v < best) { best = v; bo = p; }
        }
        nd[mid] = best;
        rec(lo, mid - 1, ol, bo);
        rec(mid + 1, hi, bo, oh);
    }
